  const playerType=type==='player',tactical=playerType||weaponType!=='none',shirt=material(shirtColor,.84),accent=material(accentColor,.72),skin=material(playerType?0xd1a17e:0xb98770,.91),pants=material(playerType?outfit.pants:type==='npc'?0x384b42:0x303942,.88),boots=material(0x302c24,.78),hairMat=material(playerType?0x211b19:0x222628,.9),eyeWhite=material(0xf1e8dc,.48),iris=material(0x43352d,.42),brow=material(playerType?0x352a28:0x302c29,.92),belt=material(0x353437,.72),metal=material(0xbac4c2,.35,.55),vestMat=material(playerType?0x596744:0x4e5a42,.86),pouchMat=material(0x69734f,.9),gloveMat=material(0x4c5542,.93);
  skin.map=proceduralSkinTexture();skin.needsUpdate=true;if(tactical){shirt.map=proceduralCamoTexture();pants.map=proceduralCamoTexture();shirt.needsUpdate=true;pants.needsUpdate=true;}
