  const torsoGeometry=new THREE.LatheGeometry(torsoProfile,40);torsoGeometry.scale(1,1,.77);const torsoPos=torsoGeometry.attributes.position,indices=[],weights=[],pelvisIndex=rigBones.indexOf(pelvisBone),chestIndex=rigBones.indexOf(chestBone);for(let i=0;i<torsoPos.count;i++){const chestWeight=THREE.MathUtils.smoothstep(torsoPos.getY(i),.94,1.37);indices.push(pelvisIndex,chestIndex,0,0);weights.push(1-chestWeight,chestWeight,0,0);}torsoGeometry.setAttribute('skinIndex',new THREE.Uint16BufferAttribute(indices,4));torsoGeometry.setAttribute('skinWeight',new THREE.Float32BufferAttribute(weights,4));
