  for(const side of [-1,1]){ellipsoid(headDetails,side*.108,1.674,0,.023,.046,.032,skin,20);ellipsoid(headDetails,side*.041,1.696,-.105,.018,.014,.01,eyeWhite,20);ellipsoid(headDetails,side*.041,1.696,-.114,.008,.009,.006,iris,16);ellipsoid(headDetails,side*.041,1.719,-.106,.024,.007,.01,brow,16);}
  ellipsoid(headDetails,0,1.663,-.119,.018,.031,.024,skin,20);ellipsoid(headDetails,0,1.621,-.112,.031,.008,.008,material(0x995b59,.84),20);const hairCap=new THREE.Mesh(new THREE.SphereGeometry(.116,28,20,0,Math.PI*2,0,Math.PI*.46),hairMat);hairCap.position.set(0,1.716,0);hairCap.castShadow=true;headDetails.add(hairCap);const operatorHelmet=ellipsoid(headDetails,0,1.78,0,.13,.057,.132,vestMat,24);operatorHelmet.visible=playerType;const helmetBrim=ellipsoid(headDetails,0,1.744,-.045,.137,.018,.141,pouchMat,24);helmetBrim.visible=playerType;const visor=ellipsoid(headDetails,0,1.706,-.115,.091,.026,.015,material(0x24332d,.32,.25),20);visor.visible=playerType;
  if(playerType){ellipsoid(headDetails,0,1.623,.052,.102,.105,.061,hairMat,28);for(const side of [-1,1])ellipsoid(headDetails,side*.094,1.66,.026,.025,.067,.03,hairMat,22);const fringe=ellipsoid(headDetails,-.018,1.744,-.074,.079,.023,.037,hairMat,24);fringe.rotation.z=-.24;ellipsoid(headDetails,.038,1.735,-.055,.052,.018,.035,hairMat,20).rotation.z=.2;}else{for(const side of [-1,1])ellipsoid(headDetails,side*.101,1.665,.018,.025,.073,.028,hairMat,18);}
  const ponytail=ellipsoid(headDetails,0,1.55,.072,.047,.13,.045,hairMat,20);ponytail.visible=playerType&&CHARACTER_PRESETS.find(c=>c.id===characterId)?.gender==='หญิง';
  const backpack=new THREE.Group();box(backpack,0,1.2,.205,.245,.39,.15,material(0x435b4a,.88));box(backpack,0,1.43,.207,.21,.12,.16,material(0x526c55,.82));for(const side of [-1,1])box(backpack,side*.13,1.22,.09,.045,.34,.05,material(0x856b49,.85));backpack.visible=playerType&&backpackEnabled;chestDetails.add(backpack);
  const limbs={spine:spineBone,chest:chestBone,neck:neckBone,head:headBone};
