function setupDemoHome(){homeInteriorGroup=new THREE.Group();homeInteriorGroup.position.set(homeRoomPos[0],0,homeRoomPos[1]);homeInteriorGroup.visible=false;world.add(homeInteriorGroup);const wall=material(0xc4ae8d),floor=material(0xb39f80),wood=material(0x725b43),cloth=material(0x57736a);box(homeInteriorGroup,0,.12,0,18,.24,14,floor,false);box(homeInteriorGroup,-9,2.2,0,.35,4.4,14,wall);box(homeInteriorGroup,9,2.2,0,.35,4.4,14,wall);box(homeInteriorGroup,0,2.2,7,18,4.4,.35,wall);box(homeInteriorGroup,-4.5,2.2,-7,9,4.4,.35,wall);box(homeInteriorGroup,5.2,2.2,-7,7.6,4.4,.35,wall);box(homeInteriorGroup,-5,.65,-3,4,.55,2.8,wood);box(homeInteriorGroup,-5,1.15,-3,4,.5,2.8,material(0xc4ad8b));box(homeInteriorGroup,4,.55,2,4,.45,2.1,cloth);box(homeInteriorGroup,4,.95,1.15,4,.65,.28,cloth);box(homeInteriorGroup,0,.75,1.8,2.2,.15,1.3,wood);box(homeInteriorGroup,0,1.25,1.8,.13,1.1,.13,wood);box(homeInteriorGroup,0,1.78,1.8,1.45,.09,.13,wood);homeLoot=new THREE.Group();homeLoot.position.set(-2,0,-1);box(homeLoot,0,.38,0,.9,.65,.7,material(0x916637));const coin=material(0xffd45c,.3,.28);for(let i=0;i<5;i++){const m=new THREE.Mesh(new THREE.CylinderGeometry(.16,.16,.06,14),coin);m.rotation.x=Math.PI/2;m.position.set(-.28+i*.14,.78,.02);homeLoot.add(m);}flatCircle(homeInteriorGroup,-2,-1,1.25,0xffd45c,.04,.8);homeInteriorGroup.add(homeLoot);flatCircle(world,homeDoorPos[0],homeDoorPos[1],2,0xcaff78,.06,.8);const homeSign=makeSign('บ้าน 05 • เข้าได้ (ตัวอย่าง)','#eaffc7');homeSign.position.set(homeDoorPos[0],4,homeDoorPos[1]-1.7);homeSign.scale.set(2.8,.72,1);world.add(homeSign);homeLootTaken=false;}
function enterDemoHome(){if(homeInside)return;homeInside=true;homeInteriorGroup.visible=true;if(homeResident?.mesh){homeResident.mesh.visible=true;homeResident.mesh.position.set(homeRoomPos[0]+1.5,0,homeRoomPos[1]+3);homeResident.mesh.userData.nameplate.visible=true;}player.position.set(homeRoomPos[0],0,homeRoomPos[1]);cameraMode='third';cameraDistance=7;yaw=Math.PI;pitch=.22;playerModel.visible=true;snapCamera();updateInteractLabel();updateHud();showToast('เข้าบ้านตัวอย่าง 05 • สำรวจห้องและคุยกับชาวบ้าน AI');}
function leaveDemoHome(){if(!homeInside)return;homeInside=false;homeInteriorGroup.visible=false;if(homeResident?.mesh)homeResident.mesh.visible=false;player.position.set(homeDoorPos[0],0,homeDoorPos[1]-2);cameraMode='third';yaw=0;pitch=.32;snapCamera();updateInteractLabel();updateHud();showToast('ออกจากบ้านตัวอย่างแล้ว');}
function interactDemoHome(){if(currentZone!=='residential')return false;if(!homeInside){if(Math.hypot(player.position.x-homeDoorPos[0],player.position.z-homeDoorPos[1])<4.2){enterDemoHome();return true;}return false;}if(!homeLootTaken&&Math.hypot(player.position.x-(homeRoomPos[0]-2),player.position.z-(homeRoomPos[1]-1))<3.2){homeLootTaken=true;if(homeLoot)homeLoot.visible=false;inventoryItems.push('เงินจำลองในเกม • บ้าน 05');savePlayerState();playSfx('pickup');updateHud();showToast('เก็บเงินจำลองในเกมแล้ว • ไม่มีเงินจริง');return true;}if(Math.hypot(player.position.x-homeExitPos[0],player.position.z-homeExitPos[1])<3.5){leaveDemoHome();return true;}showToast('ชาวบ้าน AI: ยินดีต้อนรับ • เงินที่เห็นเป็นของจำลองในเกม');return true;}

function nearZipline(){if(!player||currentZone!=='shooting')return false;return ziplineEnds.some(p=>Math.hypot(p[0]-player.position.x,p[1]-player.position.z)<4.8);}
function startZipline(){if(!nearZipline()||ziplineRide)return false;const d=ziplineEnds.map(p=>Math.hypot(p[0]-player.position.x,p[1]-player.position.z)),index=d[0]<d[1]?0:1,to=ziplineEnds[1-index];ziplineRide={from:player.position.clone(),to:new THREE.Vector3(to[0],0,to[1]),t:0,duration:3.6};autoRun=false;sprinting=false;playerPosture='stand';cameraMode='third';cameraDistance=10;pitch=.26;lockedTarget=null;showToast('โหนสลิงข้ามสนาม • ปัดจอหมุนกล้องได้');updateHud();return true;}
function setupMissionInfo(){const modes={survival:`กำจัด ${missionKillsTarget} ศัตรูภายในเวลา`,drive:`ขับรถหรือมอเตอร์ไซค์ผ่าน ${driveGates.length} จุด`,loot:`เก็บเสบียง ${missionLootTarget} ชิ้น`,zipline:'ไปที่จุดโหนสลิงและขึ้นไปให้ถึงปลายทาง'};const info=document.getElementById('n3dMissionInfo');if(info)info.textContent=`เป้าหมาย: ${modes[missionMode]} • เวลา ${Math.round(missionLimit/60)} นาที`;document.querySelectorAll('[data-mission-mode]').forEach(b=>b.classList.toggle('selected',b.dataset.missionMode===missionMode));document.querySelectorAll('[data-mission-time]').forEach(b=>b.classList.toggle('selected',Number(b.dataset.missionTime)===missionLimit));}
function openMissionSetup(){missionActive=false;missionStatus='';const panel=document.getElementById('n3dMissionSetup');if(panel)panel.hidden=false;const heading=document.getElementById('n3dMissionHeading');if(heading)heading.textContent='เลือกภารกิจก่อนลงสนาม';const start=document.getElementById('n3dMissionStart');if(start)start.textContent='เริ่มลงสนาม';const cont=document.getElementById('n3dMissionContinue');if(cont)cont.hidden=false;setupMissionInfo();updateDriveGates();updateHud();}
function formatMissionTime(n){n=Math.max(0,Math.ceil(n));return `${String(Math.floor(n/60)).padStart(2,'0')}:${String(n%60).padStart(2,'0')}`;}
function startMission(){missionActive=true;missionStatus='';missionSeconds=missionLimit;missionLootCount=0;missionCheckpoint=0;missionUiTimer=0;combatKills=0;combatWave=0;waveDelay=0;bots=bots.filter(b=>{if(b.zone==='shooting'&&b.hostile){scene.remove(b.mesh);return false;}return true;});const panel=document.getElementById('n3dMissionSetup');if(panel)panel.hidden=true;const spawn=ZONES.shooting.spawn||[320,17];player.position.set(spawn[0],14,spawn[1]);grounded=false;jumpVelocity=0;playerPosture='stand';vVelocity.set(0,0,0);cameraMode='third';yaw=0;pitch=.18;playerModel.visible=true;royaleZoneElapsed=0;royaleZoneRadius=52;royaleZoneDamageTimer=0;battleRoyaleActive=missionMode==='survival';if(battleRoyaleActive)createBattleRoyaleRing();else clearBattleRoyaleRing();spawnCombatWave();updateDriveGates();updateHud();showToast(`ลงสนาม! ${Math.round(missionLimit/60)} นาที • ${missionMode==='survival'?'กำจัด 8 ศัตรู':missionMode==='drive'?'ขับผ่านจุดเช็กพอยต์':missionMode==='loot'?'เก็บเสบียง':'โหนสลิงไปปลายทาง'}`);}
function finishMission(won){if(!missionActive)return;missionActive=false;battleRoyaleActive=false;clearBattleRoyaleRing();missionStatus=won?'ภารกิจสำเร็จ':'หมดเวลา • ภารกิจไม่สำเร็จ';updateDriveGates();const panel=document.getElementById('n3dMissionSetup');if(panel)panel.hidden=false;const heading=document.getElementById('n3dMissionHeading');if(heading)heading.textContent=won?'ภารกิจสำเร็จ!':'หมดเวลา';const info=document.getElementById('n3dMissionInfo');if(info)info.textContent=won?`ทำเป้าหมายสำเร็จก่อนเวลา • เหลือ ${formatMissionTime(missionSeconds)}`:'หมดเวลาแล้ว • เลือกเริ่มภารกิจใหม่หรือกลับไปเล่นอิสระ';const start=document.getElementById('n3dMissionStart');if(start)start.textContent='เริ่มรอบใหม่';const cont=document.getElementById('n3dMissionContinue');if(cont)cont.hidden=false;updateHud();showToast(won?'ภารกิจสำเร็จ!':'หมดเวลา • ลองใหม่ได้');}
function continueFreeplay(){missionActive=false;battleRoyaleActive=false;clearBattleRoyaleRing();missionStatus='เล่นอิสระ';const panel=document.getElementById('n3dMissionSetup');if(panel)panel.hidden=true;updateDriveGates();updateHud();}
function clearBattleRoyaleRing(){if(!royaleZoneRing)return;world?.remove(royaleZoneRing);royaleZoneRing.geometry?.dispose();royaleZoneRing.material?.dispose();royaleZoneRing=null;}
function createBattleRoyaleRing(){clearBattleRoyaleRing();const materialRing=new THREE.MeshBasicMaterial({color:0x7cf8e2,transparent:true,opacity:.82,depthWrite:false});royaleZoneRing=new THREE.Mesh(new THREE.TorusGeometry(1,.055,8,96),materialRing);royaleZoneRing.rotation.x=-Math.PI/2;royaleZoneRing.position.set(320,.32,17);royaleZoneRing.scale.set(royaleZoneRadius,royaleZoneRadius,1);world.add(royaleZoneRing);}
function updateMission(dt){
  if(!missionActive)return;
  missionSeconds-=dt;
  if(battleRoyaleActive){
    royaleZoneElapsed+=dt;
    const shrink=THREE.MathUtils.clamp((royaleZoneElapsed-20)/150,0,1);
    royaleZoneRadius=52+(18-52)*shrink;
    if(royaleZoneRing)royaleZoneRing.scale.set(royaleZoneRadius,royaleZoneRadius,1);
    const outside=Math.hypot(player.position.x-320,player.position.z-17)>royaleZoneRadius;
    if(outside){royaleZoneDamageTimer-=dt;if(royaleZoneDamageTimer<=0){royaleZoneDamageTimer=.8;damagePlayer(5,'วงอันตราย');}}
    else royaleZoneDamageTimer=0;
    for(const bot of bots){if(bot.zone==='shooting'&&bot.hostile&&bot.alive&&Math.hypot(bot.mesh.position.x-320,bot.mesh.position.z-17)>royaleZoneRadius){bot.hp-=dt*8;if(bot.hp<=0)defeatBot(bot);}}
  }
  if(missionMode==='drive'&&(combatCarOccupied||combatBikeOccupied)&&driveGates[missionCheckpoint]){const g=driveGates[missionCheckpoint];if(Math.hypot(player.position.x-g.x,player.position.z-g.z)<5.6){missionCheckpoint++;showToast(`ผ่านจุด ${missionCheckpoint}/${driveGates.length}`);updateDriveGates();if(missionCheckpoint>=driveGates.length){finishMission(true);return;}}}
  if(missionMode==='loot'&&missionLootCount>=missionLootTarget){finishMission(true);return;}
  if(missionMode==='survival'&&combatKills>=missionKillsTarget){finishMission(true);return;}
  if(missionSeconds<=0){missionSeconds=0;finishMission(false);return;}
  missionUiTimer-=dt;if(missionUiTimer<=0){missionUiTimer=.65;updateHud();}
}
