function nearestBot(maxDistance=Infinity) { let best=null,dist=maxDistance; for(const b of bots){if(!b.alive||!b.hostile||b.zone!==currentZone)continue;const d=b.mesh.position.distanceTo(player.position);if(d<dist){dist=d;best=b;}}return best?{bot:best,distance:dist}:null; }
function drawTracer(end,color,origin=null){const from=(origin||camera.position).clone(),geo=new THREE.BufferGeometry().setFromPoints([from,end.clone()]),line=new THREE.Line(geo,new THREE.LineBasicMaterial({color,transparent:true,opacity:.88}));scene.add(line);bullets.push({mesh:line,life:.16,fade:.16});}
function isHeadIntersection(bot,object){const head=bot.mesh.userData.head;for(let node=object;node&&node!==bot.mesh;node=node.parent)if(node===head)return true;return false;}
function aimedTarget(range){if(!camera||!aimRaycaster)return null;camera.updateMatrixWorld(true);const direction=new THREE.Vector3();camera.getWorldDirection(direction);if(lockedTarget?.alive&&lockedTarget.zone===currentZone){const point=lockedTarget.mesh.position.clone().add(new THREE.Vector3(0,1.67,0)),distance=point.distanceTo(camera.position),cover=coverIntersection(camera.position,direction,distance);if(distance<=range&&(!cover||cover.distance>=distance-.18))return{bot:lockedTarget,distance,point,locked:true,hitZone:'head'};return null;}aimRaycaster.setFromCamera(new THREE.Vector2(0,0),camera);aimRaycaster.far=range;const candidates=bots.filter(b=>b.alive&&b.hostile&&b.zone===currentZone);for(const b of candidates)b.mesh.updateMatrixWorld(true);const cover=coverIntersection(camera.position,direction,range);let headBest=null;for(const bot of candidates){const center=bot.mesh.position.clone().add(new THREE.Vector3(0,1.675,0)),toCenter=center.clone().sub(camera.position),along=toCenter.dot(direction);if(along<=0||along>range)continue;const closest=camera.position.clone().addScaledVector(direction,along),perpendicular=closest.distanceTo(center),radius=.18;if(perpendicular>radius)continue;const distance=along-Math.sqrt(Math.max(0,radius*radius-perpendicular*perpendicular)),point=camera.position.clone().addScaledVector(direction,distance);if(distance<=range&&(!cover||cover.distance>=distance-.12)&&(!headBest||distance<headBest.distance))headBest={bot,distance,point,hitZone:'head'};}if(headBest)return headBest;const hits=aimRaycaster.intersectObjects(candidates.map(b=>b.mesh),true);if(hits.length){const hit=hits[0],bot=candidates.find(b=>b.mesh.getObjectById(hit.object.id));if(cover&&cover.distance<hit.distance-.12)return null;if(bot&&hit.distance<=range)return{bot,distance:hit.distance,point:hit.point,hitZone:isHeadIntersection(bot,hit.object)?'head':'body'};}let best=null,score=.965;for(const bot of candidates){const point=bot.mesh.position.clone().add(new THREE.Vector3(0,1.12,0)),delta=point.clone().sub(camera.position),distance=delta.length();if(distance>range||lineBlocked(camera.position,point))continue;const dot=direction.dot(delta.normalize());if(dot>score){score=dot;best={bot,distance,point,hitZone:'body'};}}return best;}
